<?php
$stats=$dashboardStats??[];$sales=$stats['ventas_7_dias']??[];$values=array_map(static fn(array $d):float=>(float)$d['total'],$sales);$maxSales=max(1,...$values);$chartPoints=[];$bars=[];
foreach($sales as $i=>$day){$x=62+$i*90;$height=((float)$day['total']/$maxSales)*145;$y=205-$height;$bars[]=['x'=>$x,'y'=>$y,'height'=>$height,'day'=>$day];$chartPoints[]=($x+21).','.$y;}
$states=$stats['estados_pedidos']??[];$stateTotal=array_sum(array_column($states,'cantidad'));$circumference=314.159;$offset=0;$stateClasses=['PENDIENTE'=>'pending','CONFIRMADO'=>'confirmed','PREPARANDO'=>'preparing','ENTREGADO'=>'delivered','CANCELADO'=>'cancelled'];$chartCssFile=dirname(__DIR__,3).'/public/assets/css/admin-chart.css';$chartCssVersion=is_file($chartCssFile)?filemtime($chartCssFile):time();
?>
<link rel="stylesheet" href="<?=e(asset('assets/css/admin-chart.css').'?v='.$chartCssVersion)?>">
<section class="admin-stat-grid"><article class="stat-teal"><i class="bi bi-cart3"></i><div><span>Ventas de hoy</span><strong><?=e(money($stats['ventas_hoy']??0))?></strong><small><i class="bi bi-check-circle"></i> Pagos aprobados</small></div></article><article class="stat-orange"><i class="bi bi-clipboard-check"></i><div><span>Pedidos pendientes</span><strong><?=e($stats['pedidos_pendientes']??0)?></strong><small><i class="bi bi-circle-fill"></i> Por gestionar</small></div></article><article class="stat-green"><i class="bi bi-box-seam"></i><div><span>Productos activos</span><strong><?=e($stats['productos_activos']??0)?></strong><small><i class="bi bi-check-circle"></i> Catálogo actualizado</small></div></article><article class="stat-red"><i class="bi bi-exclamation-triangle"></i><div><span>Stock bajo</span><strong><?=e($stats['productos_stock_bajo']??0)?></strong><small><i class="bi bi-arrow-down"></i> Requieren atención</small></div></article></section>
<div class="admin-dashboard-grid"><section class="admin-panel admin-panel--wide"><div class="admin-panel__heading"><div><span class="admin-kicker">Rendimiento</span><h2>Ventas de los últimos 7 días</h2></div><small>Valores en guaraníes</small></div><div class="sales-diagram"><svg viewBox="0 0 700 260" role="img" aria-label="Gráfico combinado de ventas aprobadas de los últimos siete días"><line class="chart-grid" x1="55" y1="60" x2="680" y2="60"/><line class="chart-grid" x1="55" y1="132" x2="680" y2="132"/><line class="chart-axis" x1="55" y1="205" x2="680" y2="205"/><text class="chart-y-label" x="5" y="64"><?=e(number_format($maxSales,0,',','.'))?></text><text class="chart-y-label" x="5" y="136"><?=e(number_format($maxSales/2,0,',','.'))?></text><text class="chart-y-label" x="35" y="209">0</text><?php foreach($bars as $bar):?><rect class="chart-bar" x="<?=e($bar['x'])?>" y="<?=e($bar['y'])?>" width="42" height="<?=e(max(1,$bar['height']))?>" rx="6"/><text class="chart-value" x="<?=e($bar['x']+21)?>" y="<?=e(max(48,$bar['y']-10))?>" text-anchor="middle"><?=e(number_format((float)$bar['day']['total'],0,',','.'))?></text><text class="chart-day" x="<?=e($bar['x']+21)?>" y="232" text-anchor="middle"><?=e((new DateTimeImmutable($bar['day']['fecha']))->format('d/m'))?></text><?php endforeach;?><polyline class="chart-line" points="<?=e(implode(' ',$chartPoints))?>"/><?php foreach($bars as $bar):?><circle class="chart-point" cx="<?=e($bar['x']+21)?>" cy="<?=e($bar['y'])?>" r="5"/><?php endforeach;?></svg></div></section>
<section class="admin-panel order-state-panel"><div><span class="admin-kicker">Distribución</span><h2>Estado de pedidos</h2></div><div class="order-donut-wrap"><svg class="order-donut" viewBox="0 0 140 140" role="img" aria-label="Distribución de pedidos por estado"><circle class="donut-track" cx="70" cy="70" r="50"/><?php foreach($states as $state):$length=$stateTotal?((int)$state['cantidad']/$stateTotal)*$circumference:0;?><circle class="donut-segment donut-<?=e($stateClasses[$state['estado']]??'cancelled')?>" cx="70" cy="70" r="50" stroke-dasharray="<?=e($length)?> <?=e($circumference-$length)?>" stroke-dashoffset="<?=e(-$offset)?>"/><?php $offset+=$length;endforeach;?><text class="donut-total" x="70" y="67" text-anchor="middle"><?=e($stateTotal)?></text><text class="donut-caption" x="70" y="85" text-anchor="middle">pedidos</text></svg><div class="order-state-legend"><?php foreach($states as $state):?><div><i class="legend-<?=e($stateClasses[$state['estado']]??'cancelled')?>"></i><span><?=e(ucfirst(strtolower($state['estado'])))?></span><strong><?=e($state['cantidad'])?></strong></div><?php endforeach;?></div></div></section></div>
<div class="admin-dashboard-grid"><section class="admin-panel admin-panel--wide"><div class="admin-panel__heading"><h2>Pedidos recientes</h2><a href="<?=e(url('admin-orders'))?>">Ver todos <i class="bi bi-arrow-right"></i></a></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Pedido</th><th>Cliente</th><th>Fecha</th><th>Estado</th><th>Total</th><th>Acción</th></tr></thead><tbody><?php foreach($stats['pedidos_recientes']??[] as $o):?><tr><td><a href="<?=e(url('admin-order',['id'=>$o['id_pedido']]))?>">#<?=e($o['id_pedido'])?></a></td><td><?=e($o['cliente'])?></td><td><?=e((new DateTimeImmutable($o['fecha_pedido']))->format('d/m/Y H:i'))?></td><td><span class="admin-status status-<?=e(strtolower($o['estado']))?>"><?=e($o['estado'])?></span></td><td><?=e(money($o['total']))?></td><td><a class="admin-outline-action" href="<?=e(url('admin-order',['id'=>$o['id_pedido']]))?>">Ver</a></td></tr><?php endforeach;?></tbody></table></div></section><section class="admin-panel stock-detail-panel"><div class="admin-panel__heading"><h2>Stock bajo</h2><a href="<?=e(url('admin-products'))?>">Ver todos</a></div><ul class="admin-stock-list"><?php foreach($stats['stock_bajo']??[] as $p):?><li><img src="<?=e(product_image($p['imagen']??null))?>" alt="" width="46" height="46"><div><strong><?=e($p['nombre'])?></strong><small><?=e($p['categoria'])?></small><span class="stock-severity <?=((int)$p['stock']<=2)?'critical':'low'?>"><?=e($p['stock'])?> unidades · <?=((int)$p['stock']<=2)?'Crítico':'Bajo'?></span></div><a class="admin-outline-action" href="<?=e(url('admin-product-edit',['id'=>$p['id_producto']]))?>">Gestionar stock</a></li><?php endforeach;?><?php if(empty($stats['stock_bajo'])):?><li>Sin productos con stock bajo.</li><?php endif;?></ul></section></div>
